#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-10-07

# Test: reference skills load inline; only task skills fork (ork-ref-skill-fork)
#
# Since CC 2.1.218 a `context: fork` skill runs in the background by default:
# the Skill call returns at once and the parent turn carries on without the
# skill's content. The CC skills docs also warn that a fork of a skill with
# guidelines but no task "receives the guidelines but no actionable prompt,
# and returns without meaningful output". A session asked for "proper e2e",
# called Skill(ork:testing-e2e), and got neither the guidance nor a run.
#
# Rule, for every skill with `user-invocable: false`:
#   - a guideline-only skill has no `context: fork` and no `agent:`, so its
#     content loads into the parent turn;
#   - a skill with real task steps (TASK_SKILLS) keeps `context: fork` and
#     sets `background: false`, so the parent waits for its result.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../../.." && pwd)"

# Non-invocable skills that run a task of their own. Adding a name here is a
# claim that the skill body is a procedure a fork can carry out alone.
TASK_SKILLS=" audit-full error-analysis "

FAILED=0
CHECKED=0

# Print the value of a top-level frontmatter key, or nothing if absent.
fm_value() {
  awk -v key="$2" '
    NR == 1 && $0 == "---" { inside = 1; next }
    inside && $0 == "---" { exit }
    inside && index($0, key ":") == 1 {
      v = substr($0, length(key) + 2)
      gsub(/^[ \t"]+|[ \t"]+$/, "", v)
      print v
      exit
    }' "$1"
}

for skill_md in "$REPO_ROOT"/src/skills/*/SKILL.md; do
  [[ "$(fm_value "$skill_md" user-invocable)" == "false" ]] || continue
  CHECKED=$((CHECKED + 1))
  name="$(basename "$(dirname "$skill_md")")"
  context="$(fm_value "$skill_md" context)"
  agent="$(fm_value "$skill_md" agent)"
  background="$(fm_value "$skill_md" background)"

  if [[ "$TASK_SKILLS" == *" $name "* ]]; then
    if [[ "$context" != "fork" || "$background" != "false" ]]; then
      echo "FAIL: $name: task skill must keep 'context: fork' and set 'background: false'"
      FAILED=1
    fi
  elif [[ "$context" == "fork" || -n "$agent" ]]; then
    echo "FAIL: $name: guideline-only skill must not set 'context: fork' or 'agent:' (a background fork returns nothing)"
    FAILED=1
  fi
done

echo ""
if [[ $CHECKED -eq 0 ]]; then
  echo "FAIL: no user-invocable:false skills found; the scan is broken"
  exit 1
fi
if [[ $FAILED -eq 0 ]]; then
  echo "OK: $CHECKED non-invocable skills; guideline skills load inline, task skills fork and wait"
fi

exit "$FAILED"
